package com.shazwan.idash3;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import org.json.*;import java.io.*;import java.util.*;
/** Additional settled-window audit of Apps and Drive, using the same capture coordinator. */
public class CraftPagesAudit extends CraftUiAudit {
 @Override public void onStart(){Bundle out=new Bundle();int code=Activity.RESULT_CANCELED;android.content.SharedPreferences p=getTargetContext().getSharedPreferences("idash",0);Map<String,?> saved=new HashMap<>(p.getAll());try{
 p.edit().putBoolean("motion",false).putInt("dock_size",0).putString("jakim_zone","SGR02").putInt("dashboard_panel",0).putBoolean("dashboard_location",false).apply();a=(LauncherActivity)startActivitySync(new Intent(getTargetContext(),LauncherActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));java.util.concurrent.CountDownLatch ready=new java.util.concurrent.CountDownLatch(2);a.worker.execute(()->a.main.post(ready::countDown));a.networkWorker.execute(()->a.main.post(ready::countDown));if(!ready.await(45,java.util.concurrent.TimeUnit.SECONDS))throw new AssertionError("data barrier");
 for(String size:new String[]{"1024x600","800x480"}){shell("wm size "+size);waitForIdleSync();for(String page:new String[]{"apps","drive"}){
  String id=page+"-"+size;ui(()->{a.page=page;a.query="";a.render();if(a.driveDashboard!=null&&a.driveDashboard.map!=null)a.driveDashboard.map.setUseDataConnection(false);});SystemClock.sleep(1000);waitForIdleSync();for(int i=0;i<100&&!a.hasWindowFocus();i++)SystemClock.sleep(100);if(!a.hasWindowFocus())throw new AssertionError("Window occluded: "+id);
  JSONObject[] data={null};ui(()->{try{JSONArray text=new JSONArray(),controls=new JSONArray();scan(a.stage,text,controls);JSONObject r=new JSONObject().put("case",id).put("window_focused",a.hasWindowFocus()).put("viewport",bounds(a.stage)).put("text",text).put("controls",controls);if(a.driveDashboard!=null)r.put("native_map",a.driveDashboard.map!=null).put("gps_tracking",a.driveDashboard.listening).put("map",bounds(a.driveDashboard.mapHost));else r.put("dock",bounds(find(a.stage,"Launcher dock")));data[0]=r;}catch(Exception e){throw new AssertionError(e);}});write("craft-"+id+".json",data[0].toString(2));File next=new File(a.getFilesDir(),"craft-next-"+id);next.delete();write("craft-ready",id);long deadline=SystemClock.uptimeMillis()+90000;while(!next.exists()&&SystemClock.uptimeMillis()<deadline)SystemClock.sleep(100);if(!next.exists())throw new AssertionError("capture timeout "+id);cases++;
 }}out.putString("stream","PASS: "+cases+" Apps/Drive cases; text candidates="+issues.size()+"\n");code=Activity.RESULT_OK;
 }catch(Throwable t){out.putString("stream","FAIL: "+t+"\n");}finally{try{shell("wm size 1024x600");}catch(Exception ignored){}if(a!=null)ui(a::finish);AppearanceChecks.restore(p,saved);}finish(code,out);}
}
